		const pi = await createHarness();
		const c = ctx(pi, true);
		await walkToLoop(pi, c);
		await pi.events.get("tool_result")(
			{ type: "tool_result", toolName: "subagent", toolCallId: "dup-builder", input: { agent: "builder" }, content: [{ type: "text", text: "done" }], isError: false },
