            await persistAfter(controller, before);
          } catch (error) {
            return {
              content: [{ type: "text", text: `Cannot end: workflow state could not be persisted: ${error instanceof Error ? error.message : String(error)}` }],
              details: { persistenceError: true },
            };
          }
