            // onArtifactMaybe below sees loop-complete.md and advances to audit.
          } else if (ls.reviewRound >= ls.maxIterations) {
            // Cap reached without a clean review. Notify once, stop driving.
            const wasMaxed = ls.stage === "maxed";
            ls.stage = "maxed";
            if (!wasMaxed) {
