          return {
            kind: "terminalNeedsArtifacts",
            phase: this.phase,
            missing: file,
            reason: sat.reason,
            promptToQueue: `Terminal artifact ${this.artifactDir}/${file} is incomplete: ${sat.reason}. Fix it, then call the explicit end workflow tool.`, 
          };
        }
