        step: this.PHASE_STEP[skipTo],
        prompt: this.promptFor(skipTo),
        skipped: next,
        entry: this.entryFor(skipTo, false),
        footer: this.footerFor(),
      };
    }
    this.setPhase(next);
    return {
      kind: "advanced",
      phase: next,
      step: this.PHASE_STEP[next],
      prompt: this.promptFor(next),
      entry: this.entryFor(next, false),
      footer: this.footerFor(),
    };
