      }
      if (sat.reason) {
        return { kind: "endBlocked", phase: this.phase, missing: file, reason: sat.reason };
      }
    }
    this.active = false;
    const entry = this.entryFor(this.phase, true);
    return {
      kind: "closed",
      phase: this.phase,
      artifactDir: this.artifactDir,
