    if (!this.active) {
      return { visible: false, statusKey: this.config.statusKey };
    }
    const step = this.PHASE_STEP[this.phase];
    return {
      visible: true,
      statusKey: this.config.statusKey,
      text: `● ${this.config.footerLabel} · ${step}/${this.totalSteps} ${this.phase}`,
